definition.script:
pipeline {
  agent any

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '30', artifactNumToKeepStr: '30'))
    timeout(time: 15, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  // Weekly Sunday ~03:00 (H = Jenkins jitter so 8 agents don't all fire the
  // same minute). Manual triggers and parameters still work normally.
  triggers {
    cron('H 3 * * 0')
  }

  stages {
    stage('Checkout') {
      steps {
        git branch: 'master', url: 'https://github.com/johndoe6345789/jenkins.git'
      }
    }

    stage('Install rotator deps') {
      steps {
        sh '''
          python3 -m pip install --user --quiet bcrypt
          python3 -c "import bcrypt; print('bcrypt', bcrypt.__version__)"
        '''
      }
    }

    stage('Status (before)') {
      steps {
        sh '''
          cd scripts/rotator
          ARGS=""
          if [ -n "${TARGETS}" ]; then ARGS="--only $(echo ${TARGETS} | tr ',' ' ')"; fi
          python3 rotate.py status $ARGS
        '''
      }
    }

    stage('Rotate') {
      steps {
        sh '''
          cd scripts/rotator
          ARGS=""
          if [ -n "${TARGETS}" ]; then ARGS="$ARGS --only $(echo ${TARGETS} | tr ',' ' ')"; fi
          if [ "${DRY_RUN}" = "true" ]; then ARGS="$ARGS --dry-run"; fi
          python3 rotate.py rotate $ARGS
        '''
      }
    }

    // env_var targets do NOT auto-recreate their consuming containers — env
    // vars are baked at container creation. Print the list so operators (or a
    // follow-up job) know what to recreate. db_bcrypt + keycloak_realm
    // targets take effect immediately and need no action here.
    stage('Recreate plan (env_var targets)') {
      when { expression { params.DRY_RUN == false } }
      steps {
        sh '''
          python3 - <<'PY'
import json
from pathlib import Path
m = json.loads(Path('scripts/rotator/manifest.json').read_text())
hist = Path('secrets/rotated.history.json')
if not hist.exists():
    print('no history file — nothing rotated')
    raise SystemExit(0)
records = json.loads(hist.read_text())
last_ts = records[-1]['ts'] if records else None
just_rotated = {r['name'] for r in records if r['ts'] == last_ts and r['result'] == 'ok'}
to_recreate = []
for t in m['targets']:
    if t['name'] in just_rotated and t['adapter'] == 'env_var':
        svc = t['params'].get('recreate_service')
        if svc:
            to_recreate.append((t['name'], svc))
if not to_recreate:
    print('no env_var targets rotated — no containers need recreating')
else:
    print('Containers that should be recreated to pick up new env values:')
    for name, svc in to_recreate:
        print(f'  - {svc}    (target: {name})')
    print()
    print('One-liner per service (resolves the compose project from container labels):')
    for _, svc in to_recreate:
        print(f'''  cid=$(docker ps -aqf name=^{svc}$); \\
    cfg=$(docker inspect $cid --format '{{{{ index .Config.Labels "com.docker.compose.project.config_files" }}}}'); \\
    proj=$(docker inspect $cid --format '{{{{ index .Config.Labels "com.docker.compose.project" }}}}'); \\
    svc=$(docker inspect $cid --format '{{{{ index .Config.Labels "com.docker.compose.service" }}}}'); \\
    docker compose -f "$cfg" -p "$proj" up -d --no-deps --force-recreate "$svc"''')
PY
        '''
      }
    }
  }

  post {
    always {
      // Snapshot artifacts so prior rotations remain recoverable from the
      // Jenkins UI even after workspace cleanup. secrets/ is gitignored, so
      // these only exist in the just-finished workspace.
      archiveArtifacts artifacts: 'secrets/rotated/**, secrets/rotated.env, secrets/rotated.history.json',
                       allowEmptyArchive: true,
                       fingerprint: false
      cleanWs()
    }
  }
}
